@@ -0,0 +1,43 @@
+<?php
+
+declare(strict_types=1);
+
+namespace Toolkit\LocGuard\Cli;
+
+/**
+ * One parsed CLI option carrying a string value.
+ *
+ * @property-read string $key
+ * @property-read string $value
+ * @property-read bool $consumesNext
+ */
+final class LocGuardCliValueOption
+{
+    /**
+     * Creates one normalized value option.
+     */
+    public function __construct(
+        /** @readonly */
+        private string $key,
+        /** @readonly */
+        private string $value,
+        /** @readonly */
+        private bool $consumesNext,
+    ) {
+    }
+
+    /**
+     * Provides read-only access to the immutable properties.
+     *
+     * @return mixed the value of the requested property
+     */
+    public function __get(string $name): mixed
+    {
+        return match ($name) {
+            'key' => $this->key,
+            'value' => $this->value,
+            'consumesNext' => $this->consumesNext,
+            default => null,
+        };
+    }
+}
diff --git a/src/LocGuard/Cli/LocGuardCliValueOptionParser.php b/src/LocGuard/Cli/LocGuardCliValueOptionParser.php
new file mode 100644
index 0000000..fc04985
--- /dev/null
+++ b/src/LocGuard/Cli/LocGuardCliValueOptionParser.php
@@ -0,0 +1,56 @@
+<?php
+
+declare(strict_types=1);
+
+namespace Toolkit\LocGuard\Cli;
+
+use function sprintf;
+use function strlen;
+
+use Toolkit\LocGuard\LocGuardException;
+
+/**
+ * Parses LocGuard CLI options that carry a string value.
+ */
+final class LocGuardCliValueOptionParser
+{
+    /** @var array<string, string> */
+    private const OPTIONS = [
+        '--config' => 'config',
+        '--explain' => 'explain',
+        '--reporter' => 'reporter',
+        '--format' => 'reporter',
+    ];
+
+    /**
+     * Parses an exact or equals-form value option when recognized.
+     *
+     * @param list<string> $argv
+     *
+     * @throws LocGuardException when a recognized option has no value
+     */
+    public function parse(array $argv, int $index): ?LocGuardCliValueOption
+    {
+        $argument = $argv[$index];
+        foreach (self::OPTIONS as $option => $key) {
+            if ($argument === $option) {
+                if (!isset($argv[$index + 1]) || str_starts_with($argv[$index + 1], '-')) {
+                    throw new LocGuardException(sprintf('Missing value for %s.', $option));
+                }
+
+                return new LocGuardCliValueOption($key, $argv[$index + 1], true);
+            }
+
+            if (str_starts_with($argument, $option . '=')) {
+                $value = substr($argument, strlen($option) + 1);
+                if ($value === '') {
+                    throw new LocGuardException(sprintf('Missing value for %s.', $option));
+                }
+
+                return new LocGuardCliValueOption($key, $value, false);
+            }
+        }
+
+        return null;
+    }
+}
